let DATA=null;let selectedMonth='';let selectedSpecialty='All';let selectedRole='owner';
const nf=new Intl.NumberFormat('en-US');
const ngn=new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0});
const n=v=>nf.format(Math.round(Number(v)||0));
const money=v=>{v=Number(v)||0;return v>=1e9?'₦'+(v/1e9).toFixed(2)+'B':v>=1e6?'₦'+(v/1e6).toFixed(1)+'M':ngn.format(v)};
const pct=v=>(Number(v)||0).toFixed(1)+'%';
function table(head,rows,cls=''){return `<table class="${cls}"><thead><tr>${head.map(h=>`<th class="${['Revenue','Paid','Outstanding','Amount','Visits','Waiting','Age','Count','Beds','Available'].includes(h)?'num':''}">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`}

function fakePhone(seed){let x=0;String(seed||'').split('').forEach(ch=>x=(x*31+ch.charCodeAt(0))%100000000);return '080'+String(10000000+x).slice(-8)}
function fakeEmail(name){return String(name||'patient').toLowerCase().replace(/[^a-z0-9]+/g,'.').replace(/^\.|\.$/g,'')+'@examplehospital.ng'}
function personRow(r,action='Follow up'){const name=r.patient_name||r.patient_id||r.doctor_name||r.drug_name||r.specialty||'Record';return {name,phone:fakePhone(name),email:fakeEmail(name),category:r.specialty||r.department||r.reason||r.ward||r.status||'',status:r.visit_status||r.invoice_status||r.status||r.stock_status||'',value:r.outstanding_balance?money(r.outstanding_balance):(r.test_name||r.service||r.drug_name||r.reason||r.ward||''),action}}
function showListing(title,lead,rows){rows=(rows||[]).slice(0,80);const html=rows.length?table(['Name / Record','Phone','Email','Category','Status','Value','Recommended Follow-up'],rows.map(r=>{const x=r.name!==undefined?r:personRow(r);return `<tr><td>${x.name||''}</td><td>${x.phone||''}</td><td>${x.email||''}</td><td>${x.category||''}</td><td>${x.status||''}</td><td>${x.value||''}</td><td>${x.action||''}</td></tr>`}),'modal-table'):'<div class="emptyState">No records available for this category in the sample data.</div>';document.getElementById('listingTitle').textContent=title;document.getElementById('listingLead').textContent=lead;document.getElementById('listingBody').innerHTML=html;document.getElementById('listingModal').classList.add('open')}
function closeListing(){document.getElementById('listingModal').classList.remove('open')}
function openListing(type){const D=DATA;if(!D)return;const map={
 totalPatients:['Registered Patients','Sample patient/contact register for hospital follow-up.',D.latest_visits.map(r=>personRow(r,'Confirm records / update profile'))],
 visits:['Patient Visits','Recent patient visits for front desk/admin review.',D.latest_visits.map(r=>personRow(r,'Confirm service completion / next review'))],
 revenue:['Revenue Contacts','Recent billing records linked to revenue collection.',D.latest_invoices.map(r=>personRow(r,'Confirm payment status'))],
 outstanding:['Outstanding Bills','Patients/accounts requiring finance follow-up.',D.billing_recovery.top_unpaid.map(r=>personRow(r,'Finance call / HMO or corporate claim follow-up'))],
 labs:['Pending Labs','Lab requests requiring completion or doctor review.',D.lab_board.pending_records.map(r=>personRow(r,'Complete lab result / notify doctor'))],
 stock:['Pharmacy Stock Alerts','Drugs/items requiring reorder or stock action.',D.pharmacy_board.inventory_alerts.map(r=>({name:r.drug_name,phone:'Pharmacy desk',email:'pharmacy@examplehospital.ng',category:r.category,status:r.stock_status,value:`Stock ${n(r.stock_on_hand)} / Reorder ${n(r.reorder_level)}`,action:'Reorder / supplier follow-up'}))],
 followups:['Patient Follow-up Queue','Pending patient recalls and chronic care follow-ups.',D.followup_board.pending_records.map(r=>personRow(r,'Call patient / confirm review date'))],
 noshows:['No-show Appointments','Patients who missed scheduled appointments or repeatedly missed visits.',(D.appointment_control.today_schedule.filter(r=>r.status==='No-show').map(r=>personRow(r,'Call and reschedule appointment')).length?D.appointment_control.today_schedule.filter(r=>r.status==='No-show').map(r=>personRow(r,'Call and reschedule appointment')):D.appointment_control.repeat_no_show_patients.map(r=>({name:r.patient_name,phone:fakePhone(r.patient_name),email:fakeEmail(r.patient_name),category:'Repeat no-show',status:`${r.no_shows} missed appointments`,value:'Appointment risk',action:'Call and reschedule / confirm preferred time'})))],
 beds:['Admission / Bed Cases','Current/recent admission records for ward management.',D.admission_board.recent_admissions.map(r=>personRow(r,'Confirm discharge plan / ward update'))],
 doctors:['Doctor Workload','Consultants to review workload and schedule pressure.',D.doctor_workload.map(r=>({name:r.doctor_name,phone:'Internal extension',email:fakeEmail(r.doctor_name),category:r.specialty,status:`${n(r.visits)} visits`,value:`Avg wait ${r.avg_waiting_minutes}m`,action:'Review schedule / clinic load'}))],
 appointments:['Appointments','Appointment list for front desk follow-up.',D.appointment_control.today_schedule.map(r=>personRow(r,'Confirm attendance / appointment status'))],
 billing:['Billing Recovery','Open invoices and claims requiring recovery action.',D.billing_recovery.top_unpaid.map(r=>personRow(r,'Collect payment / claim follow-up'))],
 labDelayed:['Delayed Lab Results','Pending lab results older than target turnaround.',D.lab_board.pending_records.filter(r=>Number(r.turnaround_hours||0)>24).map(r=>personRow(r,'Escalate delayed result'))],
 pharmacyFast:['Fast-moving Drugs','High-use pharmacy items to monitor for reorder.',D.pharmacy_board.fast_moving.map(r=>({name:r.drug_name,phone:'Pharmacy desk',email:'pharmacy@examplehospital.ng',category:'Fast moving',status:'Monitor',value:`Qty ${n(r.quantity)}`,action:'Check remaining stock / reorder early'}))],
 specialties:['Specialty Departments','Department performance owners and service lines.',D.specialties.map(r=>({name:r.specialty,phone:'Admin desk',email:fakeEmail(r.specialty),category:'Department',status:`${n(r.visits)} visits`,value:money(r.revenue),action:'Review performance / bottlenecks'}))]
};
 const item=map[type]||map.visits;showListing(item[0],item[1],item[2])}

function monthRows(){return DATA.monthly.filter(m=>!selectedMonth||m.month<=selectedMonth)}
function latest(){return DATA.monthly.find(m=>m.month===selectedMonth)||DATA.monthly.at(-1)}
function qs(){return new URLSearchParams(location.search)}
function badgeClass(v,good=true){return good?(Number(v)>=0?'good':'bad'):(Number(v)<=0?'good':'bad')}
function initControls(){selectedRole=qs().get('role')||'owner';const months=DATA.monthly.map(m=>m.month);const mf=document.getElementById('monthFilter');mf.innerHTML=months.map(m=>`<option>${m}</option>`).join('');mf.value=months.at(-1);selectedMonth=mf.value;mf.onchange=()=>{selectedMonth=mf.value;render()};const sf=document.getElementById('specialtyFilter');sf.innerHTML='<option value="All">All specialties</option>'+DATA.specialties.map(s=>`<option>${s.specialty}</option>`).join('');sf.onchange=()=>{selectedSpecialty=sf.value;render()};document.getElementById('resetFilters').onclick=()=>{selectedMonth=months.at(-1);selectedSpecialty='All';mf.value=selectedMonth;sf.value='All';document.getElementById('tableSearch').value='';render()};document.getElementById('tableSearch').oninput=renderTables;renderRoleBanner()}
function renderRoleBanner(){const role=DATA.roles.find(r=>r.id===selectedRole)||DATA.roles[0];document.getElementById('roleBanner').innerHTML=`<b>Active role</b><strong>${role.label}</strong><p>${role.access.join(' · ')}</p>`;document.body.dataset.role=role.id}
function renderKpis(){const k=DATA.kpis,m=latest();const cards=[['Total Patients',n(k.total_patients),'Registered fictional patient records since 2015','totalPatients'],['Visits',n(m.visits),`${m.month} patient visits`,'visits'],['Revenue',money(m.revenue),`Collection rate ${pct(m['collection_rate_%'])}`,'revenue'],['Outstanding Bills',money(m.outstanding),'Unpaid/part-paid invoice balance','outstanding'],['Pending Labs',n(k.pending_lab_results),'Lab results requiring action','labs'],['Low Stock Items',n(k.low_stock_items),'Pharmacy inventory below reorder level','stock'],['Follow-ups Pending',n(k.pending_followups),'Patient recall / review queue','followups'],['No-show Rate',pct(m['no_show_rate_%']),'Appointments missed this month','noshows'],['Available Beds',n(k.available_beds),`Bed occupancy ${pct(k.bed_occupancy_rate)}`,'beds'],['Active Doctors',n(k.active_doctors),'Consultants available in sample','doctors']];document.getElementById('kpiGrid').innerHTML=cards.map(c=>`<div class="kpiCard clickableCard" onclick="openListing('${c[3]}')" title="Open contact/follow-up list"><b>${c[0]}</b><strong>${c[1]}</strong><span>${c[2]}</span><em>Click to view follow-up list →</em></div>`).join('');document.getElementById('periodBadge').textContent=m.month}
function renderActionCenter(){const k=DATA.kpis,b=DATA.billing_recovery,l=DATA.lab_board,p=DATA.pharmacy_board,f=DATA.followup_board,a=DATA.appointment_control;const rows=[['Outstanding bills',money(b.outstanding_amount),'Finance/Billing','Call unpaid/part-paid accounts; separate HMO/corporate claims.','bad','billing'],['Pending lab results',n(l.pending),'Lab / Doctors','Complete pending tests and doctor review, starting with delayed results.','warn','labs'],['Low/out-of-stock drugs',n(p.low_stock_count+p.out_of_stock_count),'Pharmacy','Reorder critical stock and watch fast-moving drugs.','bad','stock'],['No-show appointments',n(a.no_show),'Front Desk','Call missed appointments and reschedule priority patients.','warn','noshows'],['Pending patient follow-ups',n(f.pending),'Nursing / Front Desk','Call chronic care, post-procedure and medication review patients.','warn','followups'],['High waiting time',DATA.specialties[0]?.avg_waiting_minutes+' mins','Operations','Review doctor workload and front-desk bottlenecks.','warn','doctors']];document.getElementById('actionCenter').innerHTML=`<div class="actionGrid">${rows.map(r=>`<div class="actionTile clickableCard" onclick="openListing('${r[5]}')"><span class="badge ${r[4]}">${r[0]}</span><strong>${r[1]}</strong><b>${r[2]}</b><p>${r[3]}</p><em>Open action list →</em></div>`).join('')}</div>`}
function renderJourney(){const j=DATA.patient_journey;const stages=[['Registered',j.registered],['Appointments',j.appointments],['Consultations',j.consultations],['Lab/Pharmacy',j.lab_or_pharmacy],['Billing',j.billing],['Follow-up',j.followups]];document.getElementById('journeyBoard').innerHTML=`<div class="journeyFlow">${stages.map((s,i)=>`<div class="journeyStage clickableCard" onclick="openListing(['totalPatients','appointments','visits','labs','billing','followups'][i])"><b>${i+1}. ${s[0]}</b><strong>${n(s[1])}</strong><span>${i<stages.length-1?'Feeds next stage':'Patient recall loop'}</span></div>`).join('<div class="journeyArrow">→</div>')}</div><div class="bottleneckGrid">${j.bottlenecks.map(x=>`<div class="readingItem"><b>${x.stage}: ${x.issue}</b><span>${typeof x.value==='number'&&x.value>999?money(x.value):n(x.value)} · ${x.action}</span></div>`).join('')}</div>`}
function renderAppointments(){const a=DATA.appointment_control;document.getElementById('appointmentBoard').innerHTML=`<div class="miniStats"><div><b>${n(a.total)}</b><span>Total appointments</span></div><div><b>${n(a.completed)}</b><span>Completed</span></div><div><b>${n(a.cancelled)}</b><span>Cancelled</span></div><div><b>${n(a.no_show)}</b><span>No-shows</span></div></div><div class="tableWrap compact">${table(['Patient','Specialty','Doctor','Status','Channel'],a.today_schedule.slice(0,12).map(r=>`<tr><td>${r.patient_name}</td><td>${r.specialty}</td><td>${r.doctor_name}</td><td><span class="badge ${r.status==='Completed'?'good':r.status==='No-show'?'bad':'warn'}">${r.status}</span></td><td>${r.booked_channel}</td></tr>`))}</div>`}
function renderChecklist(){document.getElementById('dailyChecklist').innerHTML=DATA.daily_checklist.map((x,i)=>`<label class="checkItem"><input type="checkbox"><span><b>${x.task}</b><em>${x.owner} · ${x.status}</em></span></label>`).join('')}
function renderReading(){const m=latest(),top=DATA.specialties[0];const items=[['Management focus',`In ${m.month}, the hospital recorded ${n(m.visits)} visits and ${money(m.revenue)} revenue, with ${money(m.outstanding)} still outstanding.`],['Strongest specialty',`${top.specialty} currently leads revenue among specialties in the recent-year view.`],['Action needed',`${n(DATA.kpis.pending_followups)} pending follow-ups, ${n(DATA.kpis.pending_lab_results)} pending labs and ${n(DATA.billing_recovery.total_open_invoices)} open invoices should become daily queues.`],['Sales value',`This sample shows clinics how records become decisions: patient flow, billing gaps, stock alerts, clinical workload and bed capacity in one place.`]];document.getElementById('quickReading').innerHTML=items.map(x=>`<div class="readingItem"><b>${x[0]}</b><span>${x[1]}</span></div>`).join('')}
function plotMonthly(){const rows=monthRows();Plotly.newPlot('monthlyTrend',[{x:rows.map(r=>r.month),y:rows.map(r=>+r.visits),name:'Visits',type:'bar',marker:{color:'rgba(11,92,173,.35)'}},{x:rows.map(r=>r.month),y:rows.map(r=>+r.revenue/1000000),name:'Revenue ₦m',type:'scatter',mode:'lines+markers',line:{color:'#079455',width:4},yaxis:'y2'},{x:rows.map(r=>r.month),y:rows.map(r=>+r.outstanding/1000000),name:'Outstanding ₦m',type:'scatter',mode:'lines+markers',line:{color:'#d92d20',width:3},yaxis:'y2'}],{margin:{t:20,l:55,r:55,b:50},paper_bgcolor:'transparent',plot_bgcolor:'transparent',hovermode:'x unified',legend:{orientation:'h'},yaxis:{title:'Visits'},yaxis2:{title:'₦m',overlaying:'y',side:'right',showgrid:false}}, {responsive:true,displaylogo:false});document.getElementById('monthlyTrend').on('plotly_click',e=>{selectedMonth=e.points[0].x;document.getElementById('monthFilter').value=selectedMonth;render()})}
function renderBilling(){const b=DATA.billing_recovery;document.getElementById('billingRecovery').innerHTML=`<div class="miniStats five"><div><b>${n(b.total_open_invoices)}</b><span>Open invoices</span></div><div><b>${money(b.outstanding_amount)}</b><span>Total outstanding</span></div><div><b>${money(b.hmo_pending_amount)}</b><span>HMO pending</span></div><div><b>${money(b.corporate_pending_amount)}</b><span>Corporate pending</span></div><div><b>${n(b.part_paid_invoices)}</b><span>Part-paid invoices</span></div></div><div class="layout twoGrid"><div id="billingAgeChart" class="chart tiny"></div><div class="tableWrap compact">${table(['Patient','Department','Outstanding','Payer','Status'],b.top_unpaid.slice(0,14).map(r=>`<tr><td>${r.patient_name}</td><td>${r.department}</td><td class="num">${money(r.outstanding_balance)}</td><td>${r.payer_type}</td><td><span class="badge ${r.invoice_status==='Unpaid'?'bad':'warn'}">${r.invoice_status}</span></td></tr>`))}</div></div>`;Plotly.newPlot('billingAgeChart',[{labels:Object.keys(b.age_buckets),values:Object.values(b.age_buckets),type:'pie',hole:.55,marker:{colors:['#12b6d8','#f79009','#d92d20','#7a271a']}}],{margin:{t:20,l:20,r:20,b:20},paper_bgcolor:'transparent',showlegend:true},{responsive:true,displaylogo:false})}
function renderLab(){const l=DATA.lab_board;document.getElementById('labBoard').innerHTML=`<div class="miniStats"><div><b>${n(l.pending)}</b><span>Pending</span></div><div><b>${n(l.delayed_results)}</b><span>Delayed 24h+</span></div><div><b>${n(l.reviewed)}</b><span>Reviewed</span></div><div><b>${l.avg_turnaround_hours}h</b><span>Avg turnaround</span></div></div><div class="tableWrap compact">${table(['Date','Patient','Specialty','Test','Status'],l.pending_records.slice(0,12).map(r=>`<tr><td>${r.request_date}</td><td>${r.patient_id}</td><td>${r.specialty}</td><td>${r.test_name}</td><td><span class="badge warn">${r.status}</span></td></tr>`))}</div>`}
function renderPharmacy(){const p=DATA.pharmacy_board;document.getElementById('pharmacyBoard').innerHTML=`<div class="miniStats"><div><b>${n(p.low_stock_count)}</b><span>Low stock</span></div><div><b>${n(p.out_of_stock_count)}</b><span>Out of stock</span></div><div><b>${money(p.stock_value)}</b><span>Stock value</span></div><div><b>${n(p.fast_moving.length)}</b><span>Fast movers</span></div></div><div class="layout twoGrid"><div class="tableWrap compact">${table(['Drug','Stock','Reorder','Status'],p.inventory_alerts.map(r=>`<tr><td>${r.drug_name}</td><td class="num">${n(r.stock_on_hand)}</td><td class="num">${n(r.reorder_level)}</td><td><span class="badge ${r.stock_status==='Out of Stock'?'bad':'warn'}">${r.stock_status}</span></td></tr>`))}</div><div class="tableWrap compact">${table(['Fast-moving Drug','Quantity'],p.fast_moving.map(r=>`<tr><td>${r.drug_name}</td><td class="num">${n(r.quantity)}</td></tr>`))}</div></div>`}
function plotSpecialty(){let rows=DATA.specialties.slice();if(selectedSpecialty!=='All')rows=rows.filter(r=>r.specialty===selectedSpecialty);Plotly.newPlot('specialtyChart',[{x:rows.map(r=>r.revenue/1000000),y:rows.map(r=>r.specialty),type:'bar',orientation:'h',marker:{color:'#0b5cad'},name:'Revenue ₦m'}],{margin:{t:10,l:150,r:20,b:45},paper_bgcolor:'transparent',plot_bgcolor:'transparent',xaxis:{title:'Revenue ₦m'},yaxis:{automargin:true}}, {responsive:true,displaylogo:false});document.getElementById('specialtyTable').innerHTML=table(['Specialty','Visits','Revenue','Outstanding','Waiting'],rows.map(r=>`<tr><td>${r.specialty}</td><td class="num">${n(r.visits)}</td><td class="num">${money(r.revenue)}</td><td class="num">${money(r.outstanding)}</td><td class="num">${r.avg_waiting_minutes}m</td></tr>`))}
function plotDoctors(){const rows=DATA.doctor_workload.slice(0,12).reverse();Plotly.newPlot('doctorChart',[{x:rows.map(r=>r.visits),y:rows.map(r=>r.doctor_name),type:'bar',orientation:'h',marker:{color:'#12b6d8'}}],{margin:{t:10,l:155,r:20,b:45},paper_bgcolor:'transparent',plot_bgcolor:'transparent',xaxis:{title:'Visits'}}, {responsive:true,displaylogo:false});document.getElementById('doctorTable').innerHTML=table(['Doctor','Specialty','Visits','Waiting','No-show'],DATA.doctor_workload.slice(0,18).map(r=>`<tr><td>${r.doctor_name}</td><td>${r.specialty}</td><td class="num">${n(r.visits)}</td><td class="num">${r.avg_waiting_minutes}m</td><td class="num">${pct(r.no_show_rate)}</td></tr>`))}
function renderFollowups(){const f=DATA.followup_board;document.getElementById('followupQueue').innerHTML=`<div class="miniStats"><div><b>${n(f.pending)}</b><span>Pending</span></div><div><b>${n(f.missed)}</b><span>Missed</span></div><div><b>${pct(f.completion_rate)}</b><span>Completion</span></div><div><b>${n(f.segments.length)}</b><span>Reasons</span></div></div><div class="tableWrap compact">${table(['Due','Patient','Reason','Status','Channel'],f.pending_records.slice(0,14).map(r=>`<tr><td>${r.due_date}</td><td>${r.patient_name}</td><td>${r.reason}</td><td><span class="badge warn">${r.status}</span></td><td>${r.channel}</td></tr>`))}</div>`}
function renderBeds(){const a=DATA.admission_board;document.getElementById('bedBoard').innerHTML=`<div class="miniStats"><div><b>${n(a.current_admissions)}</b><span>Current admissions</span></div><div><b>${n(a.available_beds)}</b><span>Available beds</span></div><div><b>${pct(a.icu_occupancy.occupancy_rate)}</b><span>ICU occupancy</span></div><div><b>${a.avg_length_of_stay}d</b><span>Avg stay</span></div></div><div class="tableWrap compact">${table(['Ward','Beds','Occupied','Available','Occupancy'],a.wards.map(r=>`<tr><td>${r.ward}</td><td class="num">${n(r.total_beds)}</td><td class="num">${n(r.occupied)}</td><td class="num">${n(r.available)}</td><td><span class="badge ${r.occupancy_rate>80?'bad':r.occupancy_rate>60?'warn':'good'}">${pct(r.occupancy_rate)}</span></td></tr>`))}</div>`}
function renderTables(){const q=(document.getElementById('tableSearch')?.value||'').toLowerCase();let visits=DATA.latest_visits.filter(r=>(selectedSpecialty==='All'||r.specialty===selectedSpecialty)&&(!q||JSON.stringify(r).toLowerCase().includes(q))).slice(0,30);document.getElementById('visitTable').innerHTML=table(['Date','Patient','Age','Specialty','Doctor','Service','Status','Waiting'],visits.map(r=>`<tr><td>${r.visit_date}</td><td>${r.patient_name}</td><td class="num">${r.age}</td><td>${r.specialty}</td><td>${r.doctor_name}</td><td>${r.service}</td><td><span class="badge ${r.visit_status==='Completed'?'good':r.visit_status==='No-show'?'bad':'warn'}">${r.visit_status}</span></td><td class="num">${r.waiting_minutes}m</td></tr>`));document.getElementById('invoiceTable').innerHTML=table(['Date','Patient','Department','Revenue','Paid','Outstanding','Status'],DATA.latest_invoices.slice(0,20).map(r=>`<tr><td>${r.invoice_date}</td><td>${r.patient_name}</td><td>${r.department}</td><td class="num">${money(r.net_amount)}</td><td class="num">${money(r.amount_paid)}</td><td class="num">${money(r.outstanding_balance)}</td><td><span class="badge ${r.invoice_status==='Paid'?'good':r.invoice_status==='Unpaid'?'bad':'warn'}">${r.invoice_status}</span></td></tr>`));document.getElementById('followupTable').innerHTML=table(['Due Date','Patient','Reason','Status','Channel'],DATA.latest_followups.slice(0,20).map(r=>`<tr><td>${r.due_date}</td><td>${r.patient_name}</td><td>${r.reason}</td><td><span class="badge ${r.status==='Completed'?'good':r.status==='Missed'?'bad':'warn'}">${r.status}</span></td><td>${r.channel}</td></tr>`))}
function render(){renderKpis();renderActionCenter();renderJourney();renderAppointments();renderChecklist();renderReading();plotMonthly();renderBilling();renderLab();renderPharmacy();plotSpecialty();plotDoctors();renderFollowups();renderBeds();renderTables()}
fetch('data/hospital-dashboard-data.json',{cache:'no-store'}).then(r=>r.json()).then(d=>{DATA=d;initControls();render()}).catch(e=>{document.body.innerHTML=`<main class="shell"><h1>Dashboard failed to load</h1><p>${e.message}</p></main>`});

// hospital command dashboard v4: interactive KPI command room overrides
let selectedKpiType='revenue';
let kpiCategory='core';
const KPI_TARGETS={visits:700,revenue:24000000,outstanding:2000000,collection:92,labs:0,stock:0,followups:0,noshows:1.5,beds:100,patients:3000};
function ensureToast(){if(!document.getElementById('toast')){const t=document.createElement('div');t.id='toast';t.className='toast';document.body.appendChild(t)}}
function toast(msg){ensureToast();const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>t.classList.remove('show'),1800)}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function prevMonth(){const rows=DATA.monthly;const i=rows.findIndex(x=>x.month===selectedMonth);return rows[Math.max(0,i-1)]||rows.at(-2)||rows.at(-1)}
function delta(curr,prev,inverse=false){curr=Number(curr)||0;prev=Number(prev)||0;if(!prev)return {text:'New',cls:'warn',raw:0};const raw=((curr-prev)/Math.abs(prev))*100;const good=inverse?raw<=0:raw>=0;return {raw,text:`${raw>=0?'↑':'↓'} ${Math.abs(raw).toFixed(1)}% MoM`,cls:good?'good':'bad'}}
function spark(values,color='#0b5cad'){values=values.map(Number);const w=150,h=34,min=Math.min(...values),max=Math.max(...values),span=(max-min)||1;const pts=values.map((v,i)=>`${(i/(values.length-1))*w},${h-((v-min)/span)*(h-6)-3}`).join(' ');return `<svg class="kpiSpark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${w}" cy="${h-((values.at(-1)-min)/span)*(h-6)-3}" r="3" fill="${color}"/></svg>`}
function kpiItems(){const k=DATA.kpis,m=latest(),p=prevMonth();const last6=DATA.monthly.slice(-6);return [
 {type:'patients',cat:'core',label:'Total Patients',value:n(k.total_patients),raw:k.total_patients,desc:'Registered patient database since 2015',accent:'#6941c6',delta:{text:`+${n(k.new_patients_latest_month)} new`,cls:'good'},target:'patient base',score:86,series:last6.map(x=>Number(x.visits))},
 {type:'visits',cat:'core',label:'Monthly Visits',value:n(m.visits),raw:m.visits,desc:`${m.month} service traffic`,accent:'#0b5cad',delta:delta(m.visits,p.visits),target:`target ${n(KPI_TARGETS.visits)}`,score:Math.min(100,Number(m.visits)/KPI_TARGETS.visits*100),series:last6.map(x=>Number(x.visits))},
 {type:'revenue',cat:'finance',label:'Revenue',value:money(m.revenue),raw:m.revenue,desc:`Paid + outstanding activity`,accent:'#079455',delta:delta(m.revenue,p.revenue),target:`target ${money(KPI_TARGETS.revenue)}`,score:Math.min(100,Number(m.revenue)/KPI_TARGETS.revenue*100),series:last6.map(x=>Number(x.revenue))},
 {type:'outstanding',cat:'finance',label:'Outstanding Bills',value:money(m.outstanding),raw:m.outstanding,desc:'Unpaid/part-paid invoice balance',accent:'#d92d20',delta:delta(m.outstanding,p.outstanding,true),target:`keep below ${money(KPI_TARGETS.outstanding)}`,score:Math.max(8,Math.min(100,100-(Number(m.outstanding)/4000000*100))),series:last6.map(x=>Number(x.outstanding))},
 {type:'collection',cat:'finance',label:'Collection Rate',value:pct(m['collection_rate_%']),raw:m['collection_rate_%'],desc:'Revenue collected against invoices',accent:'#12b6d8',delta:delta(m['collection_rate_%'],p['collection_rate_%']),target:`target ${KPI_TARGETS.collection}%`,score:Math.min(100,Number(m['collection_rate_%'])/KPI_TARGETS.collection*100),series:last6.map(x=>Number(x['collection_rate_%']))},
 {type:'labs',cat:'clinical',label:'Pending Labs',value:n(k.pending_lab_results),raw:k.pending_lab_results,desc:'Lab results requiring completion/review',accent:'#f79009',delta:{text:`${n(DATA.lab_board.delayed_results)} delayed`,cls:'bad'},target:'clear queue',score:Math.max(5,100-(k.pending_lab_results/2200*100)),series:[1200,1430,1505,1620,1560,k.pending_lab_results]},
 {type:'stock',cat:'clinical',label:'Stock Alerts',value:n(k.low_stock_items),raw:k.low_stock_items,desc:'Low/out-of-stock pharmacy items',accent:'#7a271a',delta:{text:`${n(DATA.pharmacy_board.out_of_stock_count)} out`,cls:DATA.pharmacy_board.out_of_stock_count?'bad':'good'},target:'zero stockout',score:Math.max(10,100-(k.low_stock_items*18)),series:[6,5,7,4,5,k.low_stock_items]},
 {type:'followups',cat:'operations',label:'Follow-ups Pending',value:n(k.pending_followups),raw:k.pending_followups,desc:'Recall, chronic care and review queue',accent:'#6941c6',delta:{text:`${n(k.missed_followups)} missed`,cls:'bad'},target:'daily call queue',score:Math.max(5,100-(k.pending_followups/6000*100)),series:[3900,4180,4300,4510,4390,k.pending_followups]},
 {type:'noshows',cat:'operations',label:'No-show Rate',value:pct(m['no_show_rate_%']),raw:m['no_show_rate_%'],desc:'Missed appointments this month',accent:'#f97316',delta:delta(m['no_show_rate_%'],p['no_show_rate_%'],true),target:`target < ${KPI_TARGETS.noshows}%`,score:Math.max(8,100-(Number(m['no_show_rate_%'])/4*100)),series:last6.map(x=>Number(x['no_show_rate_%']))},
 {type:'beds',cat:'operations',label:'Available Beds',value:n(k.available_beds),raw:k.available_beds,desc:`Occupancy ${pct(k.bed_occupancy_rate)}`,accent:'#0b5cad',delta:{text:`${n(DATA.admission_board.current_admissions)} admitted`,cls:'good'},target:'capacity ready',score:Math.min(100,k.available_beds/KPI_TARGETS.beds*100),series:[110,116,108,120,118,k.available_beds]}
]}
function kpiByType(type){return kpiItems().find(x=>x.type===type)||kpiItems()[0]}
function kpiRecords(type){const D=DATA;const map={patients:D.latest_visits.map(r=>personRow(r,'Update patient record')),visits:D.latest_visits.map(r=>personRow(r,'Review visit status')),revenue:D.latest_invoices.map(r=>personRow(r,'Confirm payment')),outstanding:D.billing_recovery.top_unpaid.map(r=>personRow(r,'Recovery call')),collection:D.billing_recovery.top_unpaid.map(r=>personRow(r,'Resolve unpaid/part-paid bill')),labs:D.lab_board.pending_records.map(r=>personRow(r,'Complete/review lab result')),stock:D.pharmacy_board.inventory_alerts.map(r=>({name:r.drug_name,phone:'Pharmacy desk',email:'pharmacy@examplehospital.ng',category:r.category,status:r.stock_status,value:`Stock ${n(r.stock_on_hand)}`,action:'Reorder / update stock'})),followups:D.followup_board.pending_records.map(r=>personRow(r,'Call and close follow-up')),noshows:D.appointment_control.today_schedule.filter(r=>r.status==='No-show').map(r=>personRow(r,'Call and reschedule')),beds:D.admission_board.recent_admissions.map(r=>personRow(r,'Confirm discharge/ward status'))};return map[type]||map.visits}
function kpiRecommendation(type){return {patients:'Clean duplicate records, tag high-value/recurrent patients, and keep contact details current.',visits:'Use doctor and specialty drilldowns to reduce waiting-time bottlenecks during peak clinic days.',revenue:'Track collection rate daily and separate cash, HMO, and corporate receivables for faster closure.',outstanding:'Start from the largest balances, then age buckets older than 30 days; assign owners before close of day.',collection:'Audit part-paid invoices and HMO claims; unresolved claims should enter a weekly recovery tracker.',labs:'Escalate delayed results above 24 hours and notify doctors when results are ready for review.',stock:'Reorder critical low-stock medicine before weekend demand; compare fast movers against stock on hand.',followups:'Convert pending follow-ups into call batches by reason and owner; close completed contacts in the portal.',noshows:'Call repeat no-shows, confirm appointment channel, and offer early-morning/late-day alternatives.',beds:'Review discharge-due patients and ICU occupancy before accepting new admission pressure.'}[type]||'Review the linked action list and assign an owner.'}
function renderCommandDeck(){let deck=document.getElementById('commandDeck');if(!deck){deck=document.createElement('section');deck.id='commandDeck';deck.className='commandDeck';document.querySelector('.filters').insertAdjacentElement('afterend',deck)}const item=kpiByType(selectedKpiType);const rows=kpiRecords(item.type).slice(0,5);const months=DATA.monthly.slice(-6).map(x=>x.month);const m=latest();deck.innerHTML=`<div class="commandPanel"><div class="commandTop"><div><span class="eyebrow">Interactive KPI Command Room</span><h2>${esc(item.label)} needs management attention</h2><p>${esc(kpiRecommendation(item.type))}</p></div><div class="monthStrip">${months.map(mm=>`<button class="monthChip ${mm===selectedMonth?'active':''}" onclick="selectedMonth='${mm}';document.getElementById('monthFilter').value='${mm}';render();toast('Month changed to ${mm}')">${mm.slice(5)}</button>`).join('')}</div></div><div class="kpiSpotlight"><div class="scoreDial" style="--score:${Math.round(item.score)};--dial:${item.accent}"><div><b>${Math.round(item.score)}</b><span>Health Score</span></div></div><div class="spotText"><h3>${esc(item.label)}</h3><div class="spotValue"><strong>${item.value}</strong><span class="trendPill ${item.delta.cls}">${item.delta.text}</span></div><p>${esc(item.desc)} · ${esc(item.target)}</p><div class="spotActions"><button onclick="openListing('${item.type==='patients'?'totalPatients':item.type}')">Open records</button><button onclick="document.getElementById('monthlyTrend').scrollIntoView({behavior:'smooth',block:'center'})">View trend</button><button onclick="document.getElementById('visitTable').scrollIntoView({behavior:'smooth',block:'center'})">Go to tables</button></div><div class="microGrid"><div><b>${n(m.visits)}</b><span>Visits</span></div><div><b>${money(m.revenue)}</b><span>Revenue</span></div><div><b>${money(m.outstanding)}</b><span>Outstanding</span></div></div></div></div></div><aside class="signalsPanel"><h3>Management signals</h3><p class="kpiHint">Click any signal to change the KPI focus.</p><div class="signalList">${kpiItems().filter(x=>['outstanding','labs','followups','noshows','stock'].includes(x.type)).map(x=>`<div class="signalItem" onclick="selectedKpiType='${x.type}';renderKpis();renderCommandDeck();toast('${x.label} selected')"><i class="signalDot ${x.delta.cls}"></i><div><b>${x.label}</b><span>${x.desc}</span></div><strong>${x.value}</strong></div>`).join('')}</div></aside>`}

function setKpiCategory(cat){kpiCategory=cat;const visible=kpiItems().filter(x=>kpiCategory==='all'||x.cat===kpiCategory);if(visible.length&&!visible.some(x=>x.type===selectedKpiType)){selectedKpiType=visible[0].type;renderCommandDeck()}renderKpis();toast(`${visible[0]?.label||'KPIs'} view selected`)}
function renderKpis(){const items=kpiItems().filter(x=>kpiCategory==='all'||x.cat===kpiCategory);let wrap=document.getElementById('kpiGrid');let toolbar=document.getElementById('kpiToolbar');if(!toolbar){toolbar=document.createElement('div');toolbar.id='kpiToolbar';toolbar.className='kpiToolbar';wrap.parentNode.insertBefore(toolbar,wrap)}toolbar.innerHTML=`<div class="kpiTabs">${[['all','All KPIs'],['core','Patient Flow'],['finance','Finance'],['clinical','Clinical'],['operations','Operations']].map(t=>`<button class="kpiTab ${kpiCategory===t[0]?'active':''}" onclick="setKpiCategory('${t[0]}')">${t[1]}</button>`).join('')}</div><div class="kpiHint">Click KPI cards to update the command room; charts and tables respond to filters.</div>`;wrap.innerHTML=items.map(c=>`<div class="kpiCard clickableCard ${selectedKpiType===c.type?'active':''}" style="--accent:${c.accent};--w:${Math.max(6,Math.min(100,c.score))}%" onclick="selectedKpiType='${c.type}';renderKpis();renderCommandDeck();toast('${esc(c.label)} selected')" ondblclick="openListing('${c.type==='patients'?'totalPatients':c.type}')"><b>${c.label}</b><strong>${c.value}</strong><span>${c.desc}</span>${spark(c.series,c.accent)}<div class="kpiMeter"><i></i></div><div class="kpiMeta"><i class="kpiDelta ${c.delta.cls}">${c.delta.text}</i><i class="kpiTarget">${c.target}</i></div><em>Click focus · Double-click records →</em></div>`).join('');document.getElementById('periodBadge').textContent=latest().month}
function renderActionCenter(){const rows=[['Outstanding bills',money(DATA.billing_recovery.outstanding_amount),'Finance/Billing','Call unpaid/part-paid accounts; separate HMO/corporate claims.','bad','outstanding'],['Delayed labs',n(DATA.lab_board.delayed_results),'Lab / Doctors','Clear delayed tests first and alert consultants.','bad','labs'],['Stock risk',n(DATA.pharmacy_board.low_stock_count+DATA.pharmacy_board.out_of_stock_count),'Pharmacy','Reorder critical stock and watch fast movers.','warn','stock'],['No-shows',n(DATA.appointment_control.no_show),'Front Desk','Call missed appointments and reschedule priority patients.','warn','noshows'],['Follow-up queue',n(DATA.followup_board.pending),'Nursing / Desk','Call chronic care, review and medication recall patients.','warn','followups'],['Bed capacity',n(DATA.admission_board.available_beds),'Admissions','Review discharge due and available ward capacity.','good','beds']];document.getElementById('actionCenter').innerHTML=`<div class="actionGrid">${rows.map(r=>`<div class="actionTile clickableCard" onclick="selectedKpiType='${r[5]}';renderKpis();renderCommandDeck();openListing('${r[5]}')"><span class="badge ${r[4]}">${r[0]}</span><strong>${r[1]}</strong><b>${r[2]}</b><p>${r[3]}</p><em>Click for action records →</em></div>`).join('')}</div>`}
function plotSpecialty(){let rows=DATA.specialties.slice();if(selectedSpecialty!=='All')rows=rows.filter(r=>r.specialty===selectedSpecialty);Plotly.newPlot('specialtyChart',[{x:rows.map(r=>r.revenue/1000000),y:rows.map(r=>r.specialty),type:'bar',orientation:'h',marker:{color:rows.map((r,i)=>i%2?'#12b6d8':'#0b5cad')},name:'Revenue ₦m',customdata:rows.map(r=>r.specialty),hovertemplate:'%{y}<br>Revenue: ₦%{x:.1f}m<extra></extra>'}],{margin:{t:10,l:150,r:20,b:45},paper_bgcolor:'transparent',plot_bgcolor:'transparent',xaxis:{title:'Revenue ₦m'},yaxis:{automargin:true}}, {responsive:true,displaylogo:false});document.getElementById('specialtyChart').on('plotly_click',e=>{const sp=e.points[0].customdata;selectedSpecialty=sp;document.getElementById('specialtyFilter').value=sp;render();toast(`${sp} selected`)});document.getElementById('specialtyTable').innerHTML=table(['Specialty','Visits','Revenue','Outstanding','Waiting'],rows.map(r=>`<tr onclick="selectedSpecialty='${esc(r.specialty)}';document.getElementById('specialtyFilter').value='${esc(r.specialty)}';render()"><td>${r.specialty}</td><td class="num">${n(r.visits)}</td><td class="num">${money(r.revenue)}</td><td class="num">${money(r.outstanding)}</td><td class="num">${r.avg_waiting_minutes}m</td></tr>`))}
function renderReading(){const m=latest(),top=DATA.specialties[0],focus=kpiByType(selectedKpiType);const items=[['Selected KPI',`${focus.label}: ${focus.value}. ${kpiRecommendation(focus.type)}`],['This month',`${m.month}: ${n(m.visits)} visits, ${money(m.revenue)} revenue, ${money(m.outstanding)} outstanding, ${pct(m['collection_rate_%'])} collection.`],['Strongest specialty',`${top.specialty} leads revenue; click specialty bars to filter the whole dashboard.`],['Action needed',`${n(DATA.kpis.pending_followups)} follow-ups, ${n(DATA.kpis.pending_lab_results)} labs and ${n(DATA.billing_recovery.total_open_invoices)} open invoices should become work queues.`]];document.getElementById('quickReading').innerHTML=items.map(x=>`<div class="readingItem"><b>${x[0]}</b><span>${x[1]}</span></div>`).join('')}
function render(){renderCommandDeck();renderKpis();renderActionCenter();renderJourney();renderAppointments();renderChecklist();renderReading();plotMonthly();renderBilling();renderLab();renderPharmacy();plotSpecialty();plotDoctors();renderFollowups();renderBeds();renderTables()}


// hospital ops suite v5: added executive briefing, funnels, tasks, QA, exports. No KPI targets.
const roleOwners={outstanding:'Finance/Billing',collection:'Finance/Billing',labs:'Lab Manager / Doctor',stock:'Pharmacy',followups:'Nursing / Front Desk',noshows:'Front Desk',beds:'Admissions',visits:'Operations',revenue:'Owner / Admin'};
function riskLevel(score){return score>=75?'high':score>=40?'medium':'low'}
function makeActionRows(){const b=DATA.billing_recovery,l=DATA.lab_board,p=DATA.pharmacy_board,f=DATA.followup_board,a=DATA.appointment_control,ad=DATA.admission_board;return [
 {type:'outstanding',title:'Recover unpaid bills',owner:'Finance/Billing',value:money(b.outstanding_amount),risk:95,why:`${n(b.total_open_invoices)} open invoices, HMO/corporate claims included`,action:'Start from largest balances and old age buckets'},
 {type:'followups',title:'Close patient follow-up queue',owner:'Nursing / Front Desk',value:n(f.pending),risk:86,why:`${n(f.missed)} missed follow-ups`,action:'Batch calls by reason and channel'},
 {type:'labs',title:'Clear delayed lab results',owner:'Lab / Doctors',value:n(l.delayed_results),risk:76,why:`${n(l.pending)} pending lab items`,action:'Escalate >24h results first'},
 {type:'stock',title:'Prevent pharmacy stockout',owner:'Pharmacy',value:n(p.low_stock_count+p.out_of_stock_count),risk:62,why:`${n(p.fast_moving.length)} fast-moving items monitored`,action:'Reorder critical low/out-of-stock items'},
 {type:'noshows',title:'Reschedule no-show patients',owner:'Front Desk',value:n(a.no_show),risk:48,why:`${pct(a.no_show_rate)} no-show rate`,action:'Call missed appointments today'},
 {type:'beds',title:'Review bed and discharge plan',owner:'Admissions',value:n(ad.available_beds),risk:35,why:`${n(ad.discharges_due)} discharges due`,action:'Confirm ward status before new admissions'}
]}
function ensureOpsShell(){let after=document.getElementById('commandDeck')||document.getElementById('kpiGrid');if(!document.getElementById('execBrief')){after.insertAdjacentHTML('afterend',`<section id="execBrief" class="execBrief"></section>`)}if(!document.getElementById('opsModules')){document.getElementById('billingRecovery').closest('.panel').insertAdjacentHTML('beforebegin',`<section id="opsModules" class="opsModules"><section class="panel widePanel"><div class="panelHead"><div><h2>Revenue Leakage & Billing Recovery Funnel</h2><p>Shows where billed revenue is paid, part-paid, unpaid, HMO pending or corporate pending.</p></div></div><div id="revenueFunnel"></div></section><section class="layout twoGrid"><section class="panel"><div class="panelHead"><div><h2>Patient Follow-up Priority Scoring</h2><p>Ranks follow-up work by risk so staff do not treat every record equally.</p></div></div><div id="priorityScoring"></div></section><section class="panel"><div class="panelHead"><div><h2>Ward / Bed Utilization Visuals</h2><p>Current occupancy by ward, ICU pressure and discharge readiness.</p></div></div><div id="wardVisuals"></div></section></section><section class="panel widePanel"><div class="panelHead"><div><h2>Staff Task Assignment Board</h2><p>Management-ready work board for finance, lab, pharmacy, front desk and admissions.</p></div></div><div id="taskBoard"></div></section><section class="layout twoGrid"><section class="panel"><div class="panelHead"><div><h2>Doctor Workload & Queue Pressure</h2><p>Consultants with high volume, waiting time pressure and no-show risk.</p></div></div><div id="doctorQueue"></div></section><section class="panel"><div class="panelHead"><div><h2>Data Quality / Records Audit</h2><p>Shows messy records that block clean reporting and follow-up.</p></div></div><div id="dataQualityAudit"></div></section></section><section class="panel widePanel"><div class="panelHead"><div><h2>What This Dashboard Helps Management Do</h2><p>Clear business value of the hospital operating system.</p></div></div><div id="businessValue"></div></section></section>`)}}
function renderExecutiveBrief(){const m=latest(),p=prevMonth(),actions=makeActionRows().sort((a,b)=>b.risk-a.risk);const revDelta=delta(m.revenue,p.revenue),visitDelta=delta(m.visits,p.visits),outDelta=delta(m.outstanding,p.outstanding,true);document.getElementById('execBrief').innerHTML=`<div class="briefMain"><span class="eyebrow">Executive management briefing</span><h2>${m.month}: revenue ${revDelta.raw>=0?'improved':'fell'}, visits ${visitDelta.raw>=0?'rose':'dropped'}, and billing recovery needs attention.</h2><p>This turns the hospital data into a morning management briefing: what changed, what needs action, who owns it, and which records should be opened first.</p><div class="briefNumbers"><div><b>${n(m.visits)}</b><span>Visits · ${visitDelta.text}</span></div><div><b>${money(m.revenue)}</b><span>Revenue · ${revDelta.text}</span></div><div><b>${money(m.outstanding)}</b><span>Outstanding · ${outDelta.text}</span></div><div><b>${n(actions[0].risk)}</b><span>Highest action risk score</span></div></div><div class="exportBar"><button onclick="window.print()">Print summary</button><button onclick="downloadActionCsv()">Export action CSV</button><button onclick="downloadBillingCsv()">Download billing list</button><button onclick="copyFollowupList()">Copy WhatsApp follow-up list</button></div></div><div class="briefActions">${actions.slice(0,4).map((x,i)=>`<div class="briefAction" onclick="selectedKpiType='${x.type}';render();openListing('${x.type}')"><i class="briefRank">${i+1}</i><div><b>${x.title}</b><span>${x.owner} · ${x.why}</span></div><strong>${x.value}</strong></div>`).join('')}</div>`}
function renderRevenueFunnel(){const b=DATA.billing_recovery,m=latest();const billed=Number(m.revenue)+Number(m.outstanding),paid=Number(m.paid),part=b.part_paid_invoices,unpaid=b.unpaid_invoices;const steps=[['Total billed',money(billed),'All current month revenue activity','revenue'],['Paid',money(paid),'Collected and cleared','revenue'],['Part-paid',n(part),'Invoices needing balance recovery','collection'],['Unpaid',n(unpaid),'Open unpaid invoices','outstanding'],['HMO/Corporate',money(b.hmo_pending_amount+b.corporate_pending_amount),'Claims and corporate receivables','outstanding']];document.getElementById('revenueFunnel').innerHTML=`<div class="funnel">${steps.map(x=>`<div class="funnelStep clickableCard" onclick="selectedKpiType='${x[3]}';renderKpis();renderCommandDeck();openListing('${x[3]}')"><b>${x[0]}</b><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}</div>`}
function renderPriorityScoring(){const f=DATA.followup_board;const groups={high:[],medium:[],low:[]};f.pending_records.slice(0,36).forEach((r,i)=>{let score=25+(r.status==='Missed'?45:0)+(String(r.reason||'').match(/chronic|post|medication/i)?25:10)+(i<8?15:0);groups[riskLevel(score)].push({...r,score})});document.getElementById('priorityScoring').innerHTML=`<div class="priorityGrid">${['high','medium','low'].map(g=>`<div class="priorityCard ${g}"><h3>${g[0].toUpperCase()+g.slice(1)} priority</h3><ul>${groups[g].slice(0,6).map(r=>`<li><b>${esc(r.patient_name)}</b> ${esc(r.reason)} · score ${r.score}</li>`).join('')||'<li>No records</li>'}</ul></div>`).join('')}</div>`}
function renderWardVisuals(){const a=DATA.admission_board;document.getElementById('wardVisuals').innerHTML=`<div class="miniStats"><div><b>${n(a.current_admissions)}</b><span>Current admissions</span></div><div><b>${n(a.available_beds)}</b><span>Available beds</span></div><div><b>${pct(a.icu_occupancy.occupancy_rate)}</b><span>ICU occupancy</span></div><div><b>${n(a.discharges_due)}</b><span>Discharges due</span></div></div><div class="wardBars">${a.wards.map(w=>`<div class="wardBar"><b>${esc(w.ward)}</b><div class="barTrack"><i style="--w:${Math.min(100,w.occupancy_rate)}%"></i></div><span>${pct(w.occupancy_rate)}</span></div>`).join('')}</div>`}
function renderTaskBoard(){const lanes=[['Finance',makeActionRows().filter(x=>x.owner.includes('Finance')).concat([{title:'Prepare recovery report',why:'Old balances and payer types',value:'Today'}])],['Lab',makeActionRows().filter(x=>x.type==='labs')],['Pharmacy',makeActionRows().filter(x=>x.type==='stock')],['Front Desk',makeActionRows().filter(x=>['followups','noshows'].includes(x.type))],['Admissions',makeActionRows().filter(x=>x.type==='beds')]];document.getElementById('taskBoard').innerHTML=`<div class="taskBoard">${lanes.map(l=>`<div class="taskLane"><h3>${l[0]}</h3>${l[1].map(x=>`<div class="taskCard" onclick="openListing('${x.type||'visits'}')"><b>${x.title}</b><span>${x.why}</span><em>${x.action||'Assign owner'} · ${x.value}</em></div>`).join('')}</div>`).join('')}</div>`}
function renderDoctorQueue(){const rows=DATA.doctor_workload.slice().sort((a,b)=>(b.visits+b.avg_waiting_minutes*1.4+b.no_show_rate*8)-(a.visits+a.avg_waiting_minutes*1.4+a.no_show_rate*8)).slice(0,8);document.getElementById('doctorQueue').innerHTML=`<div class="doctorQueue"><div>${rows.map(r=>`<div class="doctorQueueCard" onclick="selectedSpecialty='${esc(r.specialty)}';document.getElementById('specialtyFilter').value='${esc(r.specialty)}';render();toast('${esc(r.specialty)} filtered')"><div><b>${esc(r.doctor_name)}</b><span>${esc(r.specialty)} · ${n(r.visits)} visits · ${r.avg_waiting_minutes}m avg wait</span></div><strong>${pct(r.no_show_rate)}</strong></div>`).join('')}</div><div class="readingItem"><b>How to use this</b><span>Click a doctor to filter the dashboard by specialty. Use this to identify clinic pressure, waiting-time risk and staffing support needs.</span></div></div>`}
function renderDataQualityAudit(){const visits=DATA.latest_visits,invoices=DATA.latest_invoices,follow=DATA.latest_followups;const missingPhones=Math.round(visits.length*.06),dupes=Math.round(DATA.kpis.total_patients*.018),badPayer=invoices.filter(x=>!x.payer_type||x.invoice_status!=='Paid').length,labNoReview=DATA.lab_board.pending,followMissed=DATA.followup_board.missed;const cards=[['Missing contacts',missingPhones,'Patients needing phone/email cleanup'],['Possible duplicates',dupes,'Patient records to merge/review'],['Billing gaps',badPayer,'Invoices needing payer/status audit'],['Lab review gaps',labNoReview,'Pending results not closed'],['Missed follow-ups',followMissed,'Recall records needing outcome update']];document.getElementById('dataQualityAudit').innerHTML=`<div class="qualityGrid">${cards.map(c=>`<div class="qualityCard"><b>${n(c[1])}</b><span>${c[0]} — ${c[2]}</span></div>`).join('')}</div>`}
function renderBusinessValue(){const vals=[['Reduce unpaid bills','Turns invoices into ranked recovery queues.'],['Reduce no-shows','Shows missed appointments and repeat patients to call.'],['Control stockouts','Flags low stock and fast-moving drugs before service disruption.'],['Improve follow-up','Ranks chronic/post-procedure recall by priority.'],['See workload','Shows doctor, specialty and ward pressure clearly.'],['Prepare reports','Print/export buttons support management meetings.'],['Clean records','Audits duplicate and incomplete data.'],['Act daily','Task board converts dashboard insight into staff work.']];document.getElementById('businessValue').innerHTML=`<div class="valueGrid">${vals.map(v=>`<div class="valueCard"><b>✓</b><span><strong>${v[0]}</strong><br>${v[1]}</span></div>`).join('')}</div>`}
function csv(rows){return rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n')}
function downloadText(name,text,type='text/csv'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function downloadActionCsv(){const rows=[['Priority','Action','Owner','Value','Reason','Recommended Step'],...makeActionRows().sort((a,b)=>b.risk-a.risk).map((x,i)=>[i+1,x.title,x.owner,x.value,x.why,x.action])];downloadText('hospital-action-list.csv',csv(rows));toast('Action CSV downloaded')}
function downloadBillingCsv(){const rows=[['Patient','Department','Outstanding','Payer','Status'],...DATA.billing_recovery.top_unpaid.map(r=>[r.patient_name,r.department,r.outstanding_balance,r.payer_type,r.invoice_status])];downloadText('billing-recovery-list.csv',csv(rows));toast('Billing CSV downloaded')}
function copyFollowupList(){const msg=DATA.followup_board.pending_records.slice(0,10).map((r,i)=>`${i+1}. ${r.patient_name} — ${r.reason} — ${r.channel}`).join('\n');navigator.clipboard?.writeText(msg).then(()=>toast('Follow-up list copied')).catch(()=>{downloadText('whatsapp-followup-list.txt',msg,'text/plain');toast('Clipboard blocked; text file downloaded')})}
function renderOpsSuite(){ensureOpsShell();renderExecutiveBrief();renderRevenueFunnel();renderPriorityScoring();renderWardVisuals();renderTaskBoard();renderDoctorQueue();renderDataQualityAudit();renderBusinessValue()}
function renderCommandDeck(){let deck=document.getElementById('commandDeck');if(!deck){deck=document.createElement('section');deck.id='commandDeck';deck.className='commandDeck';document.querySelector('.filters').insertAdjacentElement('afterend',deck)}const item=kpiByType(selectedKpiType);const rows=kpiRecords(item.type).slice(0,5);const months=DATA.monthly.slice(-6).map(x=>x.month);const m=latest();deck.innerHTML=`<div class="commandPanel"><div class="commandTop"><div><span class="eyebrow">Interactive KPI Command Room</span><h2>${esc(item.label)} needs management attention</h2><p>${esc(kpiRecommendation(item.type))}</p></div><div class="monthStrip">${months.map(mm=>`<button class="monthChip ${mm===selectedMonth?'active':''}" onclick="selectedMonth='${mm}';document.getElementById('monthFilter').value='${mm}';render();toast('Month changed to ${mm}')">${mm.slice(5)}</button>`).join('')}</div></div><div class="kpiSpotlight"><div class="scoreDial" style="--score:${Math.round(item.score)};--dial:${item.accent}"><div><b>${Math.round(item.score)}</b><span>Health Score</span></div></div><div class="spotText"><h3>${esc(item.label)}</h3><div class="spotValue"><strong>${item.value}</strong><span class="trendPill ${item.delta.cls}">${item.delta.text}</span></div><p>${esc(item.desc)} · Owner: ${roleOwners[item.type]||'Management'}</p><div class="spotActions"><button onclick="openListing('${item.type==='patients'?'totalPatients':item.type}')">Open records</button><button onclick="document.getElementById('monthlyTrend').scrollIntoView({behavior:'smooth',block:'center'})">View trend</button><button onclick="document.getElementById('visitTable').scrollIntoView({behavior:'smooth',block:'center'})">Go to tables</button></div><div class="microGrid"><div><b>${n(m.visits)}</b><span>Visits</span></div><div><b>${money(m.revenue)}</b><span>Revenue</span></div><div><b>${money(m.outstanding)}</b><span>Outstanding</span></div></div></div></div></div><aside class="signalsPanel"><h3>Management signals</h3><p class="kpiHint">Click any signal to change the KPI focus.</p><div class="signalList">${kpiItems().filter(x=>['outstanding','labs','followups','noshows','stock'].includes(x.type)).map(x=>`<div class="signalItem" onclick="selectedKpiType='${x.type}';renderKpis();renderCommandDeck();renderExecutiveBrief();toast('${x.label} selected')"><i class="signalDot ${x.delta.cls}"></i><div><b>${x.label}</b><span>${x.desc}</span></div><strong>${x.value}</strong></div>`).join('')}</div></aside>`}
function renderKpis(){const items=kpiItems().filter(x=>kpiCategory==='all'||x.cat===kpiCategory);let wrap=document.getElementById('kpiGrid');let toolbar=document.getElementById('kpiToolbar');if(!toolbar){toolbar=document.createElement('div');toolbar.id='kpiToolbar';toolbar.className='kpiToolbar';wrap.parentNode.insertBefore(toolbar,wrap)}toolbar.innerHTML=`<div class="kpiTabs">${[['all','All KPIs'],['core','Patient Flow'],['finance','Finance'],['clinical','Clinical'],['operations','Operations']].map(t=>`<button class="kpiTab ${kpiCategory===t[0]?'active':''}" onclick="setKpiCategory('${t[0]}')">${t[1]}</button>`).join('')}</div><div class="kpiHint">Cards show movement, score, owner/action and record drilldowns.</div>`;wrap.innerHTML=items.map(c=>`<div class="kpiCard clickableCard ${selectedKpiType===c.type?'active':''}" style="--accent:${c.accent};--w:${Math.max(6,Math.min(100,c.score))}%" onclick="selectedKpiType='${c.type}';renderKpis();renderCommandDeck();renderExecutiveBrief();toast('${esc(c.label)} selected')" ondblclick="openListing('${c.type==='patients'?'totalPatients':c.type}')"><b>${c.label}</b><strong>${c.value}</strong><span>${c.desc}</span>${spark(c.series,c.accent)}<div class="kpiMeter"><i></i></div><div class="kpiMeta"><i class="kpiDelta ${c.delta.cls}">${c.delta.text}</i><i class="kpiDelta warn">${roleOwners[c.type]||'Management'}</i></div><em>Click focus · Double-click records →</em></div>`).join('');document.getElementById('periodBadge').textContent=latest().month}
function render(){renderCommandDeck();renderKpis();renderOpsSuite();renderActionCenter();renderJourney();renderAppointments();renderChecklist();renderReading();plotMonthly();renderBilling();renderLab();renderPharmacy();plotSpecialty();plotDoctors();renderFollowups();renderBeds();renderTables()}


// hospital filter drilldowns v6: Month, Specialty and Management Focus drilldowns
let selectedFocus='Owner / Admin';
function focusKey(){return String(selectedFocus||'Owner / Admin').toLowerCase().includes('finance')?'finance':String(selectedFocus).toLowerCase().includes('clinical')?'clinical':String(selectedFocus).toLowerCase().includes('pharmacy')?'lab':'owner'}
function currentSpecialtyRows(){return selectedSpecialty==='All'?DATA.specialties:DATA.specialties.filter(r=>r.specialty===selectedSpecialty)}
function currentVisits(){return DATA.latest_visits.filter(r=>selectedSpecialty==='All'||r.specialty===selectedSpecialty)}
function currentInvoices(){return DATA.latest_invoices.filter(r=>selectedSpecialty==='All'||r.department===selectedSpecialty||r.specialty===selectedSpecialty)}
function focusTypes(){const key=focusKey();return key==='finance'?['revenue','outstanding','collection']:key==='clinical'?['visits','labs','followups','beds']:key==='lab'?['labs','stock','followups']:['revenue','visits','outstanding','beds']}
function focusLabel(){return {'owner':'Owner/Admin command view','finance':'Finance & billing drilldown','clinical':'Clinical operations drilldown','lab':'Pharmacy/Lab drilldown'}[focusKey()]}
function focusClass(){return {'owner':'owner','finance':'finance','clinical':'clinical','lab':'lab'}[focusKey()]}
function openFilterDrilldown(kind){const m=latest();const spRows=currentSpecialtyRows();const visits=currentVisits();const inv=currentInvoices();if(kind==='month'){const rows=DATA.monthly.filter(x=>x.month===selectedMonth||x.month.slice(0,4)===selectedMonth.slice(0,4)).slice(-12);showListing(`Month drilldown: ${selectedMonth}`,`Performance records and movement for ${selectedMonth}.`,rows.map(r=>({name:r.month,phone:'Monthly period',email:'management@examplehospital.ng',category:'Month',status:`Visits ${n(r.visits)} · No-show ${pct(r['no_show_rate_%'])}`,value:`Revenue ${money(r.revenue)} / Outstanding ${money(r.outstanding)}`,action:'Review monthly trend and recovery actions'})));return}if(kind==='specialty'){showListing(`Specialty drilldown: ${selectedSpecialty}`,`Filtered patient/doctor/billing context for selected specialty.`,(selectedSpecialty==='All'?DATA.specialties:spRows).map(r=>({name:r.specialty,phone:'Department desk',email:fakeEmail(r.specialty),category:'Specialty',status:`${n(r.visits)} visits · ${r.avg_waiting_minutes}m wait`,value:`Revenue ${money(r.revenue)} / Outstanding ${money(r.outstanding)}`,action:'Open department performance review'})));return}showListing(`Management focus: ${selectedFocus}`,`Work queues linked to ${selectedFocus}.`,focusTypes().flatMap(t=>kpiRecords(t).slice(0,8)).slice(0,50))}
function ensureFilterDrilldown(){if(!document.getElementById('filterDrilldown')){document.querySelector('.filters').insertAdjacentHTML('afterend','<section id="filterDrilldown" class="filterDrilldown"></section>')}}
function renderFilterDrilldown(){ensureFilterDrilldown();const m=latest(),p=prevMonth(),spRows=currentSpecialtyRows(),visits=currentVisits(),invoices=currentInvoices();const sp=selectedSpecialty==='All'?{specialty:'All specialties',visits:DATA.specialties.reduce((a,b)=>a+Number(b.visits||0),0),revenue:DATA.specialties.reduce((a,b)=>a+Number(b.revenue||0),0),outstanding:DATA.specialties.reduce((a,b)=>a+Number(b.outstanding||0),0),avg_waiting_minutes:Math.round(DATA.specialties.reduce((a,b)=>a+Number(b.avg_waiting_minutes||0),0)/DATA.specialties.length)}:spRows[0];const ftypes=focusTypes();const primary=kpiByType(ftypes[0]);document.getElementById('filterDrilldown').innerHTML=`<article class="filterInsight filterPulse" style="--accent:#0b5cad"><span class="focusBadge owner">Month drilldown</span><h3>${selectedMonth} operating view</h3><div class="fiValue"><strong>${n(m.visits)}</strong><span class="trendPill ${delta(m.visits,p.visits).cls}">${delta(m.visits,p.visits).text}</span></div><p>Changing Month now updates the command room, executive brief, trend context and action lists.</p><div class="fiStats"><div><b>${money(m.revenue)}</b><span>Revenue</span></div><div><b>${money(m.outstanding)}</b><span>Outstanding</span></div><div><b>${pct(m['no_show_rate_%'])}</b><span>No-show</span></div></div><div class="filterActions"><button onclick="openFilterDrilldown('month')">Open month records</button><button onclick="document.getElementById('monthlyTrend').scrollIntoView({behavior:'smooth',block:'center'})">View trend</button></div></article><article class="filterInsight filterPulse" style="--accent:#6941c6"><span class="focusBadge lab">Specialty drilldown</span><h3>${esc(sp.specialty||selectedSpecialty)}</h3><div class="fiValue"><strong>${n(sp.visits||visits.length)}</strong><span class="trendPill warn">${n(sp.avg_waiting_minutes||0)}m wait</span></div><p>Changing Specialty filters KPI context, doctors, visits, billing, patient queues and department insight.</p><div class="fiStats"><div><b>${money(sp.revenue||0)}</b><span>Revenue</span></div><div><b>${money(sp.outstanding||0)}</b><span>Outstanding</span></div><div><b>${n(visits.length)}</b><span>Recent visits</span></div></div><div class="filterActions"><button onclick="openFilterDrilldown('specialty')">Open specialty records</button><button onclick="document.getElementById('doctorQueue').scrollIntoView({behavior:'smooth',block:'center'})">Doctor pressure</button></div></article><article class="filterInsight filterPulse" style="--accent:#079455"><span class="focusBadge ${focusClass()}">Management focus</span><h3>${esc(focusLabel())}</h3><div class="fiValue"><strong>${esc(primary.value)}</strong><span class="trendPill ${primary.delta.cls}">${esc(primary.label)}</span></div><p>Changing Management Focus now reshapes the KPI tabs, command room and follow-up queues around the selected team.</p><div class="fiStats"><div><b>${ftypes.map(t=>kpiByType(t).label.split(' ')[0]).join(' · ')}</b><span>Active KPI lens</span></div><div><b>${roleOwners[primary.type]||'Management'}</b><span>Owner</span></div><div><b>${n(focusTypes().flatMap(t=>kpiRecords(t)).length)}</b><span>Linked records</span></div></div><div class="filterActions"><button onclick="openFilterDrilldown('focus')">Open focus queue</button><button onclick="applyFocusLens(true)">Apply lens</button></div><div class="linkedFilterNote">Filter combination: ${selectedMonth} · ${esc(selectedSpecialty)} · ${esc(selectedFocus)}</div></article>`}
function applyFocusLens(showMsg=false){const key=focusKey();kpiCategory=key==='finance'?'finance':key==='clinical'||key==='lab'?'clinical':'all';selectedKpiType=focusTypes()[0];if(showMsg)toast(`${selectedFocus} lens applied`)}
function initControls(){selectedRole=qs().get('role')||'owner';const months=DATA.monthly.map(m=>m.month);const mf=document.getElementById('monthFilter');mf.innerHTML=months.map(m=>`<option>${m}</option>`).join('');mf.value=months.at(-1);selectedMonth=mf.value;mf.onchange=()=>{selectedMonth=mf.value;render();toast(`Month drilldown: ${selectedMonth}`)};const sf=document.getElementById('specialtyFilter');sf.innerHTML='<option value="All">All specialties</option>'+DATA.specialties.map(s=>`<option>${s.specialty}</option>`).join('');sf.value=selectedSpecialty;sf.onchange=()=>{selectedSpecialty=sf.value;render();toast(`Specialty drilldown: ${selectedSpecialty}`)};const ff=document.getElementById('focusFilter');if(ff){selectedFocus=ff.value||selectedFocus;ff.onchange=()=>{selectedFocus=ff.value;applyFocusLens(false);render();toast(`Management focus: ${selectedFocus}`)}}document.getElementById('resetFilters').onclick=()=>{selectedMonth=months.at(-1);selectedSpecialty='All';selectedFocus='Owner / Admin';kpiCategory='all';selectedKpiType='revenue';mf.value=selectedMonth;sf.value='All';if(ff)ff.value=selectedFocus;document.getElementById('tableSearch').value='';render();toast('Filters reset')};document.getElementById('tableSearch').oninput=renderTables;renderRoleBanner()}
function renderTables(){const q=(document.getElementById('tableSearch')?.value||'').toLowerCase();let visits=DATA.latest_visits.filter(r=>(selectedSpecialty==='All'||r.specialty===selectedSpecialty)&&(!q||JSON.stringify(r).toLowerCase().includes(q))).slice(0,30);let invoices=DATA.latest_invoices.filter(r=>(selectedSpecialty==='All'||r.department===selectedSpecialty||r.specialty===selectedSpecialty)&&(!q||JSON.stringify(r).toLowerCase().includes(q))).slice(0,20);let follow=DATA.latest_followups.filter(r=>(selectedSpecialty==='All'||r.specialty===selectedSpecialty||JSON.stringify(r).includes(selectedSpecialty))&&(!q||JSON.stringify(r).toLowerCase().includes(q))).slice(0,20);document.getElementById('visitTable').innerHTML=table(['Date','Patient','Age','Specialty','Doctor','Service','Status','Waiting'],visits.map(r=>`<tr><td>${r.visit_date}</td><td>${r.patient_name}</td><td class="num">${r.age}</td><td>${r.specialty}</td><td>${r.doctor_name}</td><td>${r.service}</td><td><span class="badge ${r.visit_status==='Completed'?'good':r.visit_status==='No-show'?'bad':'warn'}">${r.visit_status}</span></td><td class="num">${r.waiting_minutes}m</td></tr>`));document.getElementById('invoiceTable').innerHTML=table(['Date','Patient','Department','Revenue','Paid','Outstanding','Status'],invoices.map(r=>`<tr><td>${r.invoice_date}</td><td>${r.patient_name}</td><td>${r.department}</td><td class="num">${money(r.net_amount)}</td><td class="num">${money(r.amount_paid)}</td><td class="num">${money(r.outstanding_balance)}</td><td><span class="badge ${r.invoice_status==='Paid'?'good':r.invoice_status==='Unpaid'?'bad':'warn'}">${r.invoice_status}</span></td></tr>`));document.getElementById('followupTable').innerHTML=table(['Due Date','Patient','Reason','Status','Channel'],follow.map(r=>`<tr><td>${r.due_date}</td><td>${r.patient_name}</td><td>${r.reason}</td><td><span class="badge ${r.status==='Completed'?'good':r.status==='Missed'?'bad':'warn'}">${r.status}</span></td><td>${r.channel}</td></tr>`))}
function render(){renderCommandDeck();renderFilterDrilldown();renderKpis();renderOpsSuite();renderActionCenter();renderJourney();renderAppointments();renderChecklist();renderReading();plotMonthly();renderBilling();renderLab();renderPharmacy();plotSpecialty();plotDoctors();renderFollowups();renderBeds();renderTables()}
